//
// Live DOM Verification (see docs/dom-snapshots/inventory.json): .product_sort_container confirmed
// (option values verified live: az/za/lohi/hilo), .btn_inventory confirmed, .shopping_cart_badge
// confirmed (child of .shopping_cart_link). DISCREPANCY confirmed (documented quirk verified real):
// the product name element renders as `<div class="inventory_item_name ">` — a literal trailing
// space in the class attribute. An exact-match XPath (`@class="inventory_item_name"`) would
// silently fail against this; every locator below uses class-membership CSS (`.inventory_item_name`)
// instead, which is unaffected by the trailing space.
const PlaywrightWrapper = require("../Framework/src/helper/wrapper/PlaywrightWrappers");

class InventoryPage {
    constructor(page, logger) {
        this.page = page;
        this.logger = logger;
        this.base = new PlaywrightWrapper(page, logger);
        this.Elements = {
            inventoryItem: ".inventory_item",
            productName: ".inventory_item_name",
            productDescription: ".inventory_item_desc",
            productPrice: ".inventory_item_price",
            productImage: ".inventory_item_img img",
            addToCartButton: ".btn_inventory",
            sortDropdown: ".product_sort_container",
            cartLink: ".shopping_cart_link",
            cartBadge: ".shopping_cart_badge"
        };
    }

    async getProductCount() {
        return this.base.count(this.Elements.inventoryItem);
    }

    async getProductNames() {
        return this.base.allTextContents(this.Elements.productName);
    }

    async getProductPrices() {
        const texts = await this.base.allTextContents(this.Elements.productPrice);
        return texts.map((t) => parseFloat(t.replace("$", "")));
    }

    async getProductImageSrcs() {
        return this.page.locator(this.Elements.productImage).evaluateAll((imgs) => imgs.map((img) => img.getAttribute("src")));
    }

    /** Scopes to the specific inventory item card matching `productName` — avoids ambiguity when elements repeat. */
    getInventoryItemByName(productName) {
        return this.page.locator(this.Elements.inventoryItem).filter({ hasText: productName });
    }

    async addProductToCartByName(productName) {
        const item = this.getInventoryItemByName(productName);
        await this.base.withHeal(
            null,
            async () => {
                const btn = item.locator(this.Elements.addToCartButton);
                await btn.waitFor({ state: "visible" });
                await btn.click();
            },
            `Add to Cart (${productName})`,
            "click",
            this.Elements.addToCartButton
        );
    }

    async removeProductFromCartByName(productName) {
        const item = this.getInventoryItemByName(productName);
        await this.base.withHeal(
            null,
            async () => {
                const btn = item.locator(this.Elements.addToCartButton);
                await btn.waitFor({ state: "visible" });
                await btn.click();
            },
            `Remove from Cart (${productName})`,
            "click",
            this.Elements.addToCartButton
        );
    }

    async isProductButtonShowingRemove(productName) {
        const item = this.getInventoryItemByName(productName);
        return (await item.locator(this.Elements.addToCartButton).textContent()).trim().toLowerCase() === "remove";
    }

    async clickProductNameLink(productName) {
        const item = this.getInventoryItemByName(productName);
        await this.base.withHeal(
            null,
            async () => {
                const link = item.locator(this.Elements.productName);
                await link.waitFor({ state: "visible" });
                await link.click();
            },
            `Product Name Link (${productName})`,
            "click",
            this.Elements.productName
        );
    }

    async clickProductImage(productName) {
        const item = this.getInventoryItemByName(productName);
        await this.base.withHeal(
            null,
            async () => {
                const img = item.locator(this.Elements.productImage);
                await img.waitFor({ state: "visible" });
                await img.click();
            },
            `Product Image (${productName})`,
            "click",
            this.Elements.productImage
        );
    }

    async sortBy(optionValue) {
        await this.base.selectOption(this.Elements.sortDropdown, optionValue, "Product Sort Dropdown");
    }

    async openCart() {
        await this.base.waitAndClick(this.Elements.cartLink, "Shopping Cart Icon");
    }

    async getCartBadgeCount() {
        const visible = await this.base.isVisible(this.Elements.cartBadge);
        if (!visible) return 0;
        return parseInt(await this.base.textContent(this.Elements.cartBadge), 10);
    }

    async isCartBadgeVisible() {
        return this.base.isVisible(this.Elements.cartBadge);
    }
}

module.exports = InventoryPage;
